action.code:
// Start from the current index
for (size_t i = *tabind; i < ckh->capacity; i++) {
    // Check if the cell is occupied
    if (ckh_is_occupied(ckh, i)) {
        // Get the key and data
        *key = ckh_get_key(ckh, i);
        *data = ckh_get_data(ckh, i);
        // Advance to next position for next call
        *tabind = i + 1;
        return false; // Element found
    }
}
// No more elements
return true;

